import React, { useState, useEffect } from 'react';
import { Order } from './types';
import { apiService } from './services/apiService';
import { socketService } from './services/socketService';
import OrderCard from './components/OrderCard';
import './index.css';

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    fetchOrders();
    setupWebSocket();

    return () => {
      socketService.disconnect();
    };
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const fetchedOrders = await apiService.getOrders();
      setOrders(fetchedOrders);
      setError(null);
    } catch (err) {
      setError('Failed to fetch orders');
      console.error('Error fetching orders:', err);
    } finally {
      setLoading(false);
    }
  };

  const setupWebSocket = () => {
    socketService.connect();

    socketService.on('new-order', (event) => {
      setOrders(prev => [event.data, ...prev]);
    });

    socketService.on('order-status-update', (event) => {
      setOrders(prev => 
        prev.map(order => 
          order._id === event.orderId ? event.data : order
        )
      );
    });

    socketService.on('order-deleted', (event) => {
      setOrders(prev => prev.filter(order => order._id !== event.orderId));
    });

    setConnected(socketService.isConnected());
  };

  const handleOrderUpdate = (updatedOrder: Order) => {
    setOrders(prev => 
      prev.map(order => 
        order._id === updatedOrder._id ? updatedOrder : order
      )
    );
  };

  const handleOrderDelete = (orderId: string) => {
    setOrders(prev => prev.filter(order => order._id !== orderId));
  };

  const getStatusCounts = () => {
    const counts = {
      PENDING: 0,
      CONFIRMED: 0,
      PREPARING: 0,
      READY: 0,
      COMPLETED: 0,
      CANCELLED: 0,
    };

    orders.forEach(order => {
      counts[order.status]++;
    });

    return counts;
  };

  const statusCounts = getStatusCounts();

  if (loading && orders.length === 0) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading orders...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Kitchen Dashboard</h1>
              <p className="text-sm text-gray-600">Real-time order management</p>
            </div>
            <div className="flex items-center gap-4">
              <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm ${
                connected ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
              }`}>
                <div className={`w-2 h-2 rounded-full ${
                  connected ? 'bg-green-600' : 'bg-red-600'
                }`}></div>
                {connected ? 'Connected' : 'Disconnected'}
              </div>
              <button
                onClick={fetchOrders}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                Refresh
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Status Summary */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-yellow-800">{statusCounts.PENDING}</div>
            <div className="text-sm text-yellow-600">Pending</div>
          </div>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-blue-800">{statusCounts.CONFIRMED}</div>
            <div className="text-sm text-blue-600">Confirmed</div>
          </div>
          <div className="bg-orange-50 border border-orange-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-orange-800">{statusCounts.PREPARING}</div>
            <div className="text-sm text-orange-600">Preparing</div>
          </div>
          <div className="bg-green-50 border border-green-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-green-800">{statusCounts.READY}</div>
            <div className="text-sm text-green-600">Ready</div>
          </div>
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-gray-800">{statusCounts.COMPLETED}</div>
            <div className="text-sm text-gray-600">Completed</div>
          </div>
          <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="text-2xl font-bold text-red-800">{statusCounts.CANCELLED}</div>
            <div className="text-sm text-red-600">Cancelled</div>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
            <div className="text-red-800">{error}</div>
          </div>
        )}

        {/* Orders List */}
        {orders.length === 0 && !loading ? (
          <div className="text-center py-12">
            <div className="text-gray-400 text-lg mb-2">No orders yet</div>
            <div className="text-gray-500">New orders will appear here in real-time</div>
          </div>
        ) : (
          <div className="space-y-4">
            {orders.map(order => (
              <OrderCard
                key={order._id}
                order={order}
                onUpdate={handleOrderUpdate}
                onDelete={handleOrderDelete}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
